package com.edu.unicauca.gasstation.backend.sales.domain.models;

import java.time.Instant;
import java.util.Objects;

/** A configured target with metadata generated by the database. */
public record StoredSalesTarget(Long id, SalesTarget target, Instant createdAt) {
    public StoredSalesTarget {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(target, "target");
        Objects.requireNonNull(createdAt, "createdAt");
    }
}
